def onAppStart(app):
    app.width = 800
    app.height = 600
    app.gameOver = False
    app.rShuriLoc = '../Graphics/Shuriken/rShuriken'
    app.lShuriLoc = '../Graphics/Shuriken/lShuriken'
    app.rShuriSprite = [f'{app.rShuriLoc}/{i}-Photoroom.png' for i in range(3)]
    app.lShuriSprite = [f'{app.lShuriLoc}/{i}-Photoroom.png' for i in range(3)]
    reStart(app)
    

def reStart(app):
    # Bullet
    app.projection = []
    #AiSelection Page
    app.aiMode = None
    app.selectCounter = 0
    app.counter = 0
    #FieldSelection Page
    Game_Field.fieldSetUp(app)
    Game_Field.fieldList(app)
    app.fieldSelection = (0, 0)
    app.selectedField = None
    #Character Selection
    Game_Char.characterList(app)
    app.player1Selection = 0
    app.player2Selection = 1
    app.player1ChoseStatus = False
    app.player2ChoseStatus = False
    # Game Pause
    app.pause = False
    #Player1 Basic Info and Sprite
    app.player1 = None
    app.player1StandInd = 0
    app.player1WalkInd = 0
    app.player1AttackInd = 0
    app.player1AntiDefInd = 0
    #Player2 Basic Info and Sprite
    app.player2 = None
    app.player2StandInd = 0
    app.player2WalkInd = 0
    app.player2AttackInd = 0
    app.player2AntiDefInd = 0
    #Bullet Fly
    app.bulletRightInd = 0
    app.bulletLeftInd = 0
    #Jump points:
    app.closetJumpPoint = None



