# Draw the fighting field
def drawField(app):
    for block in app.selectedField.blocks:
        drawRect(block.x, block.y, block.sizeX, block.sizeY, fill = block.color)


def drawInstruction(app):
    # Gameover:
    if app.gameOver == True:
        drawLabel('Press r to restart', app.width/2, app.height/2+50, 
                  fill = 'red', size = 40)
        if app.aiMode == True:
            if app.player2.health == 0.1:
                drawLabel('You Win!', app.width/2, app.height/2, fill = 'red', 
                          size = 40)
            else:
                drawLabel('You Lose', app.width/2, app.height/2, fill = 'red', 
                          size = 40)
        else:
            if app.player1.health == 0.1:
                drawLabel('Player2 Win!', app.width/2, app.height/2, 
                          fill = 'red', size = 40)
            else:
                drawLabel('Player1 Win!', app.width/2, app.height/2, 
                          fill = 'red', size = 40)

def drawPlayerHealth(app):
    #Draw Player 1 lives left
    headDim1 = getImageSize(app.player1.headLoc)
    # Background
    drawRect(0, app.height - headDim1[1]*1.5, 200, headDim1[1]*1.5, 
             fill = 'purple')
    drawLabel(f'{app.player1.name}', 70, app.height - 60, fill = 'purple', 
              size = 20)
    drawRect(headDim1[0]*1.5, app.height - headDim1[1]*1.5 + 5,
             app.player1.health/5*150+0.1, headDim1[1]*1.5 - 10, fill = 'red',
             border = 'silver', borderWidth = 2)
    #Head Profile
    drawImage(app.player1.headLoc, 0, app.height - headDim1[1]*1.5, 
              width = headDim1[0]*1.5, height = headDim1[1]*1.5)
    #Draw Player 2 lives left
    drawLabel(f'{app.player2.name}', app.width - 70, app.height - 40, 
              fill = 'blue')
    headDim2 = getImageSize(app.player1.headLoc)
    # Background
    drawRect(app.width - 200, app.height - headDim2[1]*1.5, 200, 
             headDim2[1]*1.5, fill = 'blue')
    drawLabel(f'{app.player2.name}', app.width - 70, app.height - 60,
              fill = 'blue', size = 20)
    drawRect(app.width - headDim2[0]*1.5 - (app.player2.health/5*150), 
             app.height - headDim2[1]*1.5 + 5,
             app.player2.health/5*150+0.1, 
             headDim2[1]*1.5 - 10, fill = 'red',
             border = 'silver', borderWidth = 2)
    #Head Profile
    drawImage(app.player2.headLoc, 
              app.width - headDim2[0]*1.5, 
              app.height - headDim2[1]*1.5, 
              width = headDim2[0]*1.5, height = headDim2[1]*1.5)

def drawPlayer(app, player, playerAntiDefInd, playerAttackInd, playerWalkInd, 
               playerStandInd):
    if player.direction == 'left': #Direction Left
        if player.antiDefendAni:
            imageDimension = getImageSize(player.antiLDefSprite[playerAntiDefInd])
            imageWidth = imageDimension[0]
            imageHeight = imageDimension[1]
            drawImage(player.antiLDefSprite[playerAntiDefInd],
                      player.x, player.y-imageHeight/4,
                      width = imageWidth, height = imageHeight,
                      align = 'center')
        elif player.defend:
            drawCircle(player.x, player.y, 30, fill = 'red', opacity = 20, 
                       border = 'silver')
            drawImage(player.lDefLoc, player.x, player.y, align = 'center')
        elif player.attackAni:
            imageDimension = getImageSize(player.lAttackSprite[playerAttackInd])
            imageWidth = imageDimension[0]
            drawImage(player.lAttackSprite[playerAttackInd],
                      player.x, player.y,
                      width = imageWidth, height = player.sizeY,
                      align = 'center')
        elif player.walk: 
            drawImage(player.lWalkSprite[playerWalkInd], player.x, player.y,
                    width = player.sizeX, height = player.sizeY,
                    align = 'center')
        else: 
            drawImage(player.lStandSprite[playerStandInd], player.x, player.y,
                    width = player.sizeX, height = player.sizeY,
                    align = 'center')
    elif player.direction == 'right': # Direction Right
        if player.antiDefendAni:
            imageDimension = getImageSize(player.antiRDefSprite[app.player1AntiDefInd])
            imageWidth = imageDimension[0]
            imageHeight = imageDimension[1]
            drawImage(player.antiRDefSprite[app.player1AntiDefInd],
                      player.x, player.y-imageHeight/4,
                      width = imageWidth, height = imageHeight,
                      align = 'center')
        elif player.defend:
            drawCircle(player.x, player.y, 30, fill = 'red', opacity = 20, 
                       border = 'silver')
            drawImage(player.rDefLoc, player.x, player.y, align = 'center')
        elif player.attackAni:
            imageDimension = getImageSize(player.rAttackSprite[app.player1AttackInd])
            imageWidth = imageDimension[0]
            drawImage(player.rAttackSprite[app.player1AttackInd],
                      player.x, player.y,
                      width = imageWidth, height = player.sizeY,
                      align = 'center')
        elif player.walk:
            drawImage(player.rWalkSprite[app.player1WalkInd], player.x, player.y,
                    width = player.sizeX, height = player.sizeY,
                    align = 'center')
        else:
            drawImage(player.rStandSprite[app.player1StandInd], player.x, player.y,
                    width = player.sizeX, height = player.sizeY,
                    align = 'center')


def drawBullet(app):
    for bullet in app.projection:
        if bullet.velocity > 0:
            drawImage(app.rShuriSprite[app.bulletRightInd], bullet.x, 
                      bullet.y, width = bullet.sizeX, height = bullet.sizeY,
                      align = 'center')
        else:
            drawImage(app.lShuriSprite[app.bulletLeftInd], bullet.x, 
                      bullet.y, width = bullet.sizeX, height = bullet.sizeY,
                      align = 'center')

def game_onKeyPress(app, key):
    if not app.gameOver:
        #Jump
        if not app.pause:
            if not app.player1.defend:
            # Player1 Action
                if key == 'w':
                    if app.player1.jump == False:
                        app.player1.jumpChr()
                #Shoot the bullet
                if key == 'e' and app.player1.shuriCD == 0:
                    app.player1.shootChr()
                elif key == 'g' and app.player1.attackCD == 0:
                    app.player1.attackChr()
                elif key == 'f' and app.player1.antiDefCD == 0:
                    app.player1.antiDefendChr()
                    
            # Player2 Action
            if not app.player2.defend:
                if key == 'up':
                    if app.player2.jump == False:
                        app.player2.jumpChr()
                if key == 'enter' and app.player2.shuriCD == 0:
                    app.player2.shootChr()
                elif key == 'k' and app.player2.attackCD == 0:
                    app.player2.attackChr()
                elif key == ';' and app.player2.antiDefCD == 0:
                    app.player2.antiDefendChr()

                
    #Restart the game
    if app.gameOver == True:
        if key == 'r':
            setActiveScreen('start')
            reStart(app)
            app.gameOver = False

# Determine whether is in the normal attack range
def isHit(player1, player2):
    if (distance(player1.x+player1.sizeX/2, player1.y+player1.sizeY/2,
                player2.x+player2.sizeX/2, player2.y+player2.sizeY/2)
                < 50):
        return True
    else:
        return False    

def game_onKeyHold(app, keys):
    if app.gameOver:
        return
    # Still Player1 Movement
    if not app.pause:
        if 'h' in keys:
            app.player1.defend = True
        elif 'a' in keys:
            app.player1.direction = 'left'
            app.player1.walk = True #Determine Motion
            app.player1.dx = -5
        elif 'd' in keys:
            app.player1.direction = 'right'
            app.player1.walk = True
            app.player1.dx = 5
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
        
        # Player2 Movement:
        if 'l' in keys:
            app.player2.defend = True
        elif 'left' in keys:
            app.player2.direction = 'left'
            app.player2.walk = True
            app.player2.dx = -5
        elif 'right' in keys:
            app.player2.direction = 'right'
            app.player2.walk = True
            app.player2.dx = 5
    

def game_onKeyRelease(app, key):
    if app.gameOver:
        return 
    if not app.pause:
        if key == 'd' or key == 'a':
            app.player1.walk = False
            app.player1.dx = 0
        elif key == 'h':
            app.player1.defend = False
        if key == 'left' or key == 'right':
            app.player2.walk = False
            app.player2.dx = 0
        elif key == 'l':
            app.player2.defend = False

def game_onMousePress(app, mouseX, mouseY):
    if not app.gameOver:
        if not app.pause:
            if (app.width - 70 < mouseX < app.width - 20
                and 20 < mouseY < 70):
                app.pause = True
        if app.pause:
            if (app.width/2 - 100 < mouseX < app.width/2 + 100
                and app.height/4+55 < mouseY < app.height/4+105):
                app.pause = False
            if (app.width/2 - 100 < mouseX < app.width/2 + 100
                and app.height/4+175 < mouseY < app.height/4+225):
                setActiveScreen('start')
                reStart(app)


def game_onStep(app):
    if not app.gameOver:
        if not app.pause:
            if app.aiMode == True:
                BT.btAiPlayer(app).tick()
            deterGameOver(app)
            gravSimul(app)
            bulletFly(app)
            bulletHit(app)
            spriteInd(app)
            attackCD(app)
            bulletHitBlock(app)
            walkMot(app)
            boundedMotion(app)
            deterAtt(app)
            bloodFixed(app)
            app.counter += 1

# Prevent bugs where health bar can go non-positive
def bloodFixed(app):
    if app.player1.health <= 0:
        app.player1.health = 0.1
    elif app.player2.health <= 0:
        app.player2.health = 0.1

# Determine whether attack deal damage
def deterAtt(app):
    if (isHit(app.player1, app.player2) and app.player2.attack
                    and not app.player1.defend):
                    app.player1.health -= 1
                    app.player2.attack = False
    elif (isHit(app.player1, app.player2) and app.player1.attack
                    and not app.player2.defend):
                    app.player2.health -= 1
                    app.player1.attack = False
    elif (isHit(app.player1, app.player2) and app.player2.antiDefend
                    and app.player1.defend):
                    app.player1.health -= 1
                    app.player1.defend = False
                    app.player2.antiDefend = False
    elif (isHit(app.player1, app.player2) and app.player1.antiDefend
                    and app.player2.defend):
                    app.player2.health -= 1
                    app.player2.defend = False
                    app.player1.antiDefend = False


def deterGameOver(app):
    if app.player1.health == 0.1 or app.player2.health == 0.1:
        app.gameOver = True

# Count all the abilities' CD
def attackCD(app):
    #Normal Attack
    if app.player1.attackCD > 0:
        app.player1.attackCD -= 1
    if app.player2.attackCD > 0:
        app.player2.attackCD -= 1
    #Bullet
    if app.player1.shuriCD > 0:
        app.player1.shuriCD -= 1
    if app.player2.shuriCD > 0:
        app.player2.shuriCD -= 1
    #AntiDefend
    if app.player1.antiDefCD > 0:
        app.player1.antiDefCD -= 1
    if app.player2.antiDefCD > 0:
        app.player2.antiDefCD -= 1
    

# Increment the sprite image index
def spriteInd(app):
    if app.counter % 2 == 0:
        #Player1 Sprite
        app.player1StandInd = ((app.player1StandInd + 1) 
                               % len(app.player1.rStandSprite))
        app.player1WalkInd = ((app.player1WalkInd + 1) 
                              % len(app.player1.rWalkSprite))
        if app.player1.attackAni:
            if app.player1AttackInd == len(app.player1.rAttackSprite)-1:
                app.player1.attack = False
                app.player1.attackAni = False
                app.player1.attackComb = 1
                app.player1AttackInd = 0
            app.player1AttackInd += 1

        #Player2 Sprite
        app.player2StandInd = ((app.player2StandInd + 1) 
                               % len(app.player2.rStandSprite))
        app.player2WalkInd = ((app.player2WalkInd + 1) 
                              % len(app.player2.rWalkSprite))
        if app.player2.attackAni:
            if app.player2AttackInd == len(app.player2.rAttackSprite)-1:
                app.player2.attack = False
                app.player2.attackAni = False
                app.player2AttackInd = 0
            app.player2AttackInd += 1

        #Shuriken Sprite
        app.bulletRightInd = (app.bulletRightInd + 1) % len(app.rShuriSprite)
        app.bulletLeftInd = (app.bulletLeftInd + 1) % len(app.lShuriSprite)

    if app.counter % 4 == 0:
        # AntiDefense Sprite
        if app.player1.antiDefendAni:
            if app.player1AntiDefInd == len(app.player1.antiRDefSprite)-1:
                app.player1.antiDefend = False
                app.player1.antiDefendAni = False
                app.player1.antiDefCD = 30
                app.player1AntiDefInd = 0
            app.player1AntiDefInd += 1

        if app.player2.antiDefendAni:
            if app.player2AntiDefInd == len(app.player2.antiRDefSprite)-1:
                app.player2.antiDefend = False
                app.player2.antiDefendAni = False
                app.player2.antiDefCD = 30
                app.player2AntiDefInd = 0
            app.player2AntiDefInd += 1

# Determine whether character hits the block
def boundedMotion(app):
    hitBlockLeft(app, app.player1)
    hitBlockLeft(app, app.player2)
    hitBlockRight(app, app.player1)
    hitBlockRight(app, app.player2)
    hitFrame(app)

# Determine if the character hit the left or right most side
def hitFrame(app):
    if app.player1.x + app.player1.sizeX > app.width: #Bounded Motion
        app.player1.x = app.width-app.player1.sizeX
    elif app.player1.x < app.player1.sizeX/2:
        app.player1.x = app.player1.sizeX/2
    if app.player2.x + app.player2.sizeX > app.width: #Bounded Motion
        app.player2.x = app.width-app.player2.sizeX
    elif app.player2.x < 0:
        app.player2.x = 0
    
# Determine if the character hit the block on left or right side
def hitBlockRight(app, player):
    for block in app.selectedField.blocks:
        if (block.y - player.sizeY/2 <= player.y 
            <= block.y+block.sizeY+player.sizeY/2):
            if (block.x + block.sizeX - 5 <= player.x - player.sizeX/2 
                <= block.x + block.sizeX):
                player.x = block.x + block.sizeX + player.sizeX/2


def hitBlockLeft(app, player):
    for block in app.selectedField.blocks:
        if (block.y - player.sizeY/2 <= player.y 
            <= block.y+block.sizeY+player.sizeY/2):
            if (block.x <= player.x + player.sizeX/2 
                <= block.x + 5):
                player.x = block.x - player.sizeX/2



#Gravity Simulation
def gravSimul(app):

    if app.player1.jump == True:
        app.player1.dy += 3
        app.player1.y += app.player1.dy

    
    for block in app.selectedField.blocks:
        if onBlock(app.player1, block):
            app.player1.y = block.y - app.player1.sizeY/2
            app.player1.jump = False
            app.player1.dy = 0
            break
        else:
            app.player1.jump = True

        if downBlock(app.player1, block):
            app.player1.y = block.y + block.sizeY + app.player1.sizeY/2
            app.player1.dy = 0
            break

    
    # Player 2 Sim
    if app.player2.jump == True:
        app.player2.dy += 3
        app.player2.y += app.player2.dy
    
    for block in app.selectedField.blocks:
        if onBlock(app.player2, block):
            app.player2.y = block.y - app.player2.sizeY/2
            app.player2.jump = False
            app.player2.dy = 0
            break
        else:
            app.player2.jump = True
        if downBlock(app.player2, block):
            app.player2.y = block.y + block.sizeY + app.player2.sizeY/2
            app.player2.dy = 0
            break

# Perform Walk Motion
def walkMot(app):
    if not app.player1.defend:
        app.player1.x += app.player1.dx
    if not app.player2.defend:
        app.player2.x += app.player2.dx
    

# Whether the character stands on the block
def onBlock(player, block):
    if (block.x - player.sizeX/2 < player.x 
        < block.x + block.sizeX + player.sizeX/2):
        if (block.y + player.dy - player.sizeY/2 >= player.y 
            >= block.y - player.sizeY/2): #The player.dy is used to correct error off by 2-3 pixels
            return True
    return False

# Whether the character hits the bottom of the block
def downBlock(player, block):
    if (block.x - player.sizeX/2 <= player.x 
        <= block.x + block.sizeX + player.sizeX/2):
        if (block.y+block.sizeY+player.dy <= player.y-player.sizeY/2 
            <= block.y+block.sizeY):
            return True
    return False

#Bullet fly function
def bulletFly(app):
    index = 0
    while index < len(app.projection):
        app.projection[index].x += app.projection[index].velocity
        if app.projection[index].x - app.projection[index].sizeX < 0:
            app.projection.pop(index)
        elif app.projection[index].x + app.projection[index].sizeX > app.width:
            app.projection.pop(index)
        index += 1

# Bullet hit function
def bulletHit(app):
    i = 0
    while i < len(app.projection):
        if (distance(app.projection[i].x, app.projection[i].y, 
                     app.player1.x, app.player1.y)
            < app.projection[i].sizeX/2 + app.player1.sizeX/2):
            if not app.player1.defend:
                app.player1.health -= 1
            app.projection.pop(i)

        elif (distance(app.projection[i].x, app.projection[i].y, 
                       app.player2.x, app.player2.y)
            < app.projection[i].sizeX/2 + app.player2.sizeX/2):
            if not app.player2.defend:
                app.player2.health -= 1
            app.projection.pop(i)
        i += 1

#Bullet Disappear after hitting block
def bulletHitBlock(app):
    for block in app.selectedField.blocks:
        i = 0
        while i < len(app.projection):
            #Ideas from CS Academy 1.4.11
            bottom1 = app.projection[i].y + app.projection[i].sizeY/2
            right1 = app.projection[i].x + app.projection[i].sizeX/2
            bottom2 = block.y + block.sizeY
            right2 = block.x + block.sizeX
            if (bottom1 >= block.y 
                and bottom2 >= app.projection[i].y - app.projection[i].sizeY/2 
                and right1 >= block.x
                and right2 >= app.projection[i].x - app.projection[i].sizeX/2):
                app.projection.pop(i)
            i += 1
                

#Helper Function
def distance(x1, y1, x2, y2):
    return ((x1-x2)**2+(y1-y2)**2)**0.5


runAppWithScreens(initialScreen = 'start')